DECLARE d STRING;
SET d = (SELECT view_definition FROM `pacific-plating-282708.sap_data_engineer.INFORMATION_SCHEMA.VIEWS` WHERE table_name = 'sap_dashboard_carepay_fully_paid');
ASSERT TO_HEX(SHA256(d)) = 'bfbece203be80428c1e5df2ad9f4e591a43634b264b9d3a267cbe9ef8584a31e' AS 'LIVE DRIFT: sap_data_engineer.sap_dashboard_carepay_fully_paid';
