ASSERT TO_HEX(SHA256(d)) = '8d01824060e7fa9d662e0d3b21ebd47f273af4561f7258e63d60b562be3ecdc1' AS 'CANDIDATE MISMATCH: sap_data_engineer.sap_dashboard_carepay_fully_paid';
EXECUTE IMMEDIATE CONCAT('SELECT * FROM (\n', d, '\n) LIMIT 0');
